     for v,comp in colorcomp.items():
      if lab[r][cc]==comp: pred[r,cc]=v
  actual={(r,cc):h[r][cc] for r in range(R) for cc in range(C) if h[r][cc]!=g[r][cc]}
  print('demo',n,'actual',len(actual),'pred',len(pred),'miss',[(p,v) for p,v in actual.items() if pred.get(p)!=v],'extra',[(p,v) for p,v in pred.items() if actual.get(p)!=v])

